class VoltageMeasurementValueIncorrect(Exception):
    """
    Raised when one of the PM counters values of voltage is not
    within given range (40.5 - 57V)
    """
    pass


class PmCounterIncorrectValue(Exception):
    """
    Raised when one of the PM counters values is incorrect
    """
    pass


class UnexpectedEnergyConsumptionChange(Exception):
    """
    Raised when one of the values in a list of energy consumption counters
    is larger or smaller than their mean by the value greater than given deviation
    """
    pass


class MeanEnergyConsumptionValueEqualsZero(Exception):
    """
    Raised when the mean value of energy consumption counters from the specific time period
    equals 0.0 - all reported values were zero.
    """
    pass


class IncorrectNumberOfMeasurements(Exception):
    """
    Raised when number of measurements for counter is different than expected.
    """
    pass


class IncorrectMeasurementInterval(Exception):
    """
    Raised when incorrect measurement interval has been provided.
    """
    pass


class IncorrectDateTime(Exception):
    """
    Raised when incorrect datetime has been provided.
    """
    pass


class IncorrectParameterFormat(Exception):
    """
    Raised when parameter was provided with incorrect format.
    """
    pass


class IncorrectParameterValue(Exception):
    """
    Raised when parameter was provided with incorrect value.
    """
    pass


class CounterNotFound(Exception):
    """
    Raised when particular counter is not found in results
    """
    pass
